local BehaviourAction = CS.Engine.Lib.BehaviourAction
---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")
---@type ParkourGameMgr
local Mgr = import("Game.Activity.ParkourGame.ParkourGameMgr"):GetInstance()

local Collider = CS.UnityEngine.Collider
local Animator = CS.UnityEngine.Animator
local LuaParameters = CS.Engine.Modules.LuaParameters
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')
local KTool = CS.Engine.Lib.KTool
local Vector3 = CS.UnityEngine.Vector3

local CriWareUtils = import('Game.Entry.CriWareUtilsFix')

local Parkour_Loader = import('Game.Activity.ParkourGame.Parkour_Loader')


--- from: Assets/BundleResources/Prefabs/Activity/ParkourGame/WoodsLevel/81002_Done.prefab > name: 81002_Done
---@class MovingTrap:TrackTriggerItem
---@field Env                           	MovingTrap                              
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Unity_Export_Grp              	UnityEngine.Transform                   	@ 0    
local MovingTrap = Class("MovingTrap", import("Game.Activity.ParkourGame.MainGame.TrackItems.TrackTriggerItem"))


-- ============================================

local act_id = Animator.StringToHash("act")

local State = 
{
    ToLeft = 1,
    ToRight = 2,
    Dead = 3,
}


function MovingTrap:Start()
    self.super.Start(self)
    local collider = self.controller.gameObject:GetComponent(typeof(Collider))
    self.hight = collider.bounds.size.y/4 --collider.bounds.size.y  物理帧率不够,只能设置小一点

    self.initPos = self.transform.localPosition

    self.move = 0 --减少对transform的操作 float

    self.animator = KTool.GetComponent(self.controller.gameObject, typeof(Animator))

    -- !!! 走这个是不够的, 每个怪物的参数没有独立出来:
    local luaParams = CfUtils.GetOrAddComponent(self.controller.gameObject, typeof(LuaParameters))
    self.id = LuaParametersReader.Read(luaParams, "id", LuaParametersReader.Type.Int) -- 81001 这种
    self.isToLeft = LuaParametersReader.Read(luaParams, "isToLeft", LuaParametersReader.Type.Bool) -- true
    self.state = self.isToLeft and State.ToLeft or State.ToRight
    self.speed = LuaParametersReader.Read(luaParams, "speed", LuaParametersReader.Type.Float) -- 4
    self.range = LuaParametersReader.Read(luaParams, "range", LuaParametersReader.Type.Float) -- 6
    self.lScale = LuaParametersReader.Read(luaParams, "localScale", LuaParametersReader.Type.Float) -- 2

    self.deathFXGO = Parkour_Loader.GetInstance():InstanceFXGO("fx_moster_death_2", self.transform )
    self.deathFXGO.transform.localScale = Vector3.one * (1.0 / self.lScale)

end


-- 当 reset 来用:
function MovingTrap:OnEnable()    

    CfUtils.SetActive( self.deathFXGO, false )
    self.state = self.isToLeft and State.ToLeft or State.ToRight
    self.initPos = self.transform.localPosition
    self.move = 0
end


function MovingTrap:Tick(deltaTime)

    if self.state == State.Dead then 
        return

    elseif self.state == State.ToLeft then
        self.move = self.move - deltaTime * self.speed
        if self.move < -self.range then
            self.transform.localScale = Vector3(-self.lScale, self.lScale, self.lScale) -- 翻转
            self.state = State.ToRight
        end
    elseif self.state == State.ToRight then
        self.move = self.move + deltaTime * self.speed
        if self.move > self.range then
            self.transform.localScale = Vector3(self.lScale, self.lScale, self.lScale) -- 翻转
            self.state = State.ToLeft
        end
    end
    
    self.transform.localPosition = Vector3(self.initPos.x + self.move, self.initPos.y, self.initPos.z)
end

function MovingTrap:Type()
    return ParkourGameUtil.TrackItemType.MovingTrap
end

function MovingTrap:GetID()
    return self.id
end


function MovingTrap:PlayLogic(other)

    local isRole = other.name == Mgr.player.controller.gameObject.name
    if isRole then 
        return -- 不处理这个碰撞体
    end

    local idComp = KTool.GetComponent(other.gameObject, typeof(CS.Game.Native.Common.ID))
    local isRoleHit = isNotNull(idComp) and idComp.stringId == "hitCollider" -- 猫下面一层的碰撞体, 执行 hit 碰撞
    if isRoleHit == false then 
        return
    end 

    local yDis = other.transform.position.y - self.transform.position.y
    if yDis >= 0.01 then--踩头
        printInfo("MovingTrap:OnHead")

        CfUtils.SetActive( self.deathFXGO, true )

        self.animator:SetInteger( act_id, 1 ) -- 播放 death
        self.state = State.Dead
        CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "npc_disappear_12001801" )
        Mgr:Add_BeatTrap( self:GetID() )

    else
        local player = Mgr.player
        if player:OnHit(self.Type()) then
            player:SetRoleFX( "fx_role_injured_jingji", true )
        end
    end
end





return MovingTrap